448	/// Resolves a `catalog:` reference by extracting the package name from the
449	/// override key (stripping any version selector), looking it up in the named
450	/// catalog (treating an empty `catalog_name` as `"default"`), and returning
451	/// a `Version` override with the parsed version requirement.
452	///
453	/// Returns `UnresolvedCatalog` when the package name is not present in the
454	/// resolved catalog.
455	fn resolve_catalog_override(
456	  key: &str,
457	  catalog_name: &str,
458	  catalogs: &Catalogs,
459	) -> Result<NpmOverrideValue, NpmOverridesError> {
460	  let catalog_name = if catalog_name.is_empty() {
461	    "default"
462	  } else {
463	    catalog_name
464	  };
465	
466	  // the override key may include a version selector (e.g. "foo@^1.0.0"), so
467	  // strip it to get just the package name used for the catalog lookup.
468	  let package_name = if let Some(rest) = key.strip_prefix('@') {
469	    match rest.find('@') {
470	      Some(idx) => &key[..idx + 1],
471	      None => key,
472	    }
473	  } else {
474	    match key.find('@') {
475	      Some(idx) => &key[..idx],
476	      None => key,
477	    }
478	  };
479	
480	  let version_str = catalogs
481	    .get(catalog_name)
482	    .and_then(|catalog| catalog.get(package_name))
483	    .ok_or_else(|| NpmOverridesError::UnresolvedCatalog {
484	      key: key.to_string(),
